public static partial class RuleTests {
 static MatchRules matchRules;static CardCatalog catalog;static int checks,id=900000;
 static void Check(bool ok,string message){if(!ok)throw new Exception(message);checks++;}
 static MatchEngine Game(GameModeDefinition mode=null){var rules=new MatchRules(catalog);var g=new MatchEngine(catalog,rules.TrainingDeck("MAGE"),rules.TrainingDeck("WARRIOR"),42,false,mode);g.MarkMulliganCompleteForTests();foreach(var p in g.Players){p.Hand.Clear();p.Board.Clear();p.Mana=p.MaxMana=g.Mode.ManaLimit;}return g;}
 static int Hand(MatchEngine g,string card,int seat=0){int next=id++;g.Players[seat].Hand.Add(new HandCard{Id=next,CardId=card.StartsWith("GAME_")?card:"VAN_"+card});return next;}
 public static int Main(string[] args){try{catalog=CardCatalog.Load(args[0]);matchRules=new MatchRules(catalog);var suites=new Dictionary<string,Action>{{"gvg",Gvg},{"sealed",Sealed},{"naxx-library",()=>NaxxLibrary(args[0])},{"naxx-cards",NaxxCards},{"secret-owner",SecretOwner},{"effects-level",EffectsLevels},{"pyroblast",Pyroblast},{"zoo-ai",ZooAi},{"ai",FreezeMageAi},{"names",Names},{"dragons",Dragons},{"high-cost",HighCost},{"mid-cost",MidCost},{"hunter",Hunter},{"arena",Arena},{"low-cost",LowCost},{"heroes",Heroes},{"paladin",Paladin},{"shaman",Shaman},{"mage",Mage},{"priest",Priest},{"warlock",LegacyWarlock},{"druid-spells",LegacyDruidSpell},{"triggers",LegacyConditionalTrigger},{"opening",Opening},{"shadowstep",Shadowstep},{"engine",Engine},{"library",Library},{"modes",Modes},{"enchantments",Enchantments},{"privacy",Privacy},{"miracle-ai",MiracleAi},{"target-resolution",TargetResolution},{"resolution",Resolution},{"warrior",LegacyWarrior},{"secrets",LegacySecrets},{"rogue",LegacyRogue},{"deathrattle",LegacyDeathrattle},{"combo",LegacyCombo},{"overload",LegacyOverload}};var selected=args.Length<2||args[1]=="all"?suites.Keys.ToArray():args[1].Split(',');foreach(string name in selected){Action run;if(!suites.TryGetValue(name,out run))throw new Exception("Unknown rules module: "+name);int before=checks;run();Console.WriteLine("PASS "+name+": "+(checks-before));}Console.WriteLine("PASS total: "+checks+" rules checks; no WPF, TCP or user files.");return 0;}catch(Exception ex){Console.Error.WriteLine(ex);return 1;}}
 static void FreezeOpportunityRegression(){
  var g=Game();var body=g.Summon(0,"VAN_CS2_182");g.Freeze(new MatchTarget(0,body.Id));g.EndTurn();
  Check(body.Frozen,"Newborn without charge stays frozen through opponent turn");g.EndTurn();
  Check(body.Frozen&&!g.Attack(0,body.Id,new MatchTarget(1)).Success,"Newborn misses next own turn attack");g.EndTurn();Check(!body.Frozen,"Newborn thaws after missing next attack opportunity");
  g=Game();body=g.Summon(0,"VAN_CS2_171");g.Freeze(new MatchTarget(0,body.Id));g.EndTurn();Check(!body.Frozen,"Newborn with charge can thaw this turn");
  g=Game();body=g.Summon(0,"VAN_CS2_169");body.SummonTurn=0;g.Attack(0,body.Id,new MatchTarget(1));g.Freeze(new MatchTarget(0,body.Id));g.EndTurn();
  Check(!body.Frozen,"Windfury thaws after losing remaining second attack");
  g=Game();body=g.Summon(0,"VAN_CS2_169");body.SummonTurn=0;g.Attack(0,body.Id,new MatchTarget(1));g.Attack(0,body.Id,new MatchTarget(1));g.Freeze(new MatchTarget(0,body.Id));g.EndTurn();
  Check(body.Frozen,"Exhausted Windfury stays frozen");g.EndTurn();g.EndTurn();Check(!body.Frozen,"Exhausted Windfury thaws after next own turn");
  g=Game();g.Equip(0,"VAN_EX1_567");g.Attack(0,0,new MatchTarget(1));g.Freeze(new MatchTarget(0));g.EndTurn();Check(!g.Players[0].Frozen,"Windfury hero thaws after losing second attack");
  g=Game();g.Equip(0,"VAN_EX1_567");g.Attack(0,0,new MatchTarget(1));g.Attack(0,0,new MatchTarget(1));g.Freeze(new MatchTarget(0));g.EndTurn();Check(g.Players[0].Frozen,"Exhausted Windfury hero stays frozen");
  g=Game();body=g.Summon(0,"VAN_CS2_182");body.SummonTurn=0;g.Freeze(new MatchTarget(0,body.Id));g.EndTurn();Check(!body.Frozen,"Ready normal minion loses this turn attack and thaws");
  g=Game();body=g.Summon(0,"VAN_CS2_182");body.SummonTurn=0;g.Attack(0,body.Id,new MatchTarget(1));g.Freeze(new MatchTarget(0,body.Id));g.EndTurn();Check(body.Frozen,"Exhausted normal minion stays frozen");
 }
 static void LethalStatMutationRegression(){
  var g=Game();var body=g.Summon(0,"VAN_CS2_182");var target=new MatchTarget(0,body.Id);g.Damage(target,5);g.Buff(target,2,2);g.SetHealth(target,10);g.Heal(target,10);
  Check(body.Health<=0&&body.BuffAttack==0,"Shared stat and healing entry points cannot rescue lethal minion");g.Cleanup();Check(!g.Players[0].Board.Contains(body),"Lethal minion still dies exactly once");
  var living=g.Summon(0,"VAN_CS2_182");target=new MatchTarget(0,living.Id);g.Damage(target,1);g.Buff(target,1,1);Check(g.AttackValue(living)==5&&living.Health==5,"Living damaged minion still receives buff");
  g.SetHealth(target,1);Check(living.Health==1&&living.DamageTaken==0,"Living health setter still applies");
 }
 static void AttackEventRegression(){
  var g=Game();var body=g.Summon(0,"VAN_CS2_182");var enemy=g.Summon(1,"VAN_CS2_182");
  Check(!g.Attack(0,body.Id,new MatchTarget(1,enemy.Id)).Success&&!g.VisualEvents.Any(e=>e.Kind=="attack"),"Invalid attack emits no attack animation");
  body.SummonTurn=0;g.Attack(0,body.Id,new MatchTarget(1,enemy.Id));var attack=g.VisualEvents.Single(e=>e.Kind=="attack");
  Check(attack.Seat==0&&attack.UnitId==body.Id&&attack.TargetSeat==1&&attack.TargetUnitId==enemy.Id,"Attack event explicitly identifies both combatants");
  Check(g.VisualEvents.Where(e=>e.Kind=="damage").All(e=>e.Action==attack.Action&&e.Sequence>attack.Sequence),"Impact damage follows attack event in same action");
  var remote=LanProtocol.ReadView(catalog,LanProtocol.Copy(LanProtocol.View(g,1,"attack",1)));
  Check(remote.VisualEvents.Single(e=>e.Kind=="attack").TargetUnitId==enemy.Id,"Public snapshot preserves attack target identity");
  g=Game();g.Equip(0,"VAN_CS2_106");g.Attack(0,0,new MatchTarget(1));attack=g.VisualEvents.Single(e=>e.Kind=="attack");
  Check(attack.UnitId==0&&attack.TargetUnitId==0&&attack.TargetSeat==1,"Hero weapon attack uses hero anchors");
  g=Game();body=g.Summon(0,"VAN_CS2_182");body.SummonTurn=0;g.ArmSecret(1,new HandCard{Id=id++,CardId="VAN_EX1_611"});g.Attack(0,body.Id,new MatchTarget(1));
  Check(!g.VisualEvents.Any(e=>e.Kind=="attack"),"Secret-cancelled attack never lunges");
 }
 static void BurnFatiguePrivacy(){var g=Game();var p=g.Players[0];p.Hand.Clear();for(int n=0;n<10;n++)p.Hand.Add(new HandCard{Id=id++,CardId="VAN_CS2_182"});p.Deck.Clear();p.Deck.Add("VAN_CS2_029");g.Draw(0,1);var burn=g.VisualEvents.Single(e=>e.Kind=="burn");Check(burn.CardId=="VAN_CS2_029"&&burn.CardName==catalog.Card("VAN_CS2_029").Name,"Burn event identifies burned card");Check(g.Log.Any(line=>line.Contains("爆牌：")&&line.Contains(catalog.Card("VAN_CS2_029").Name)),"Shared log reveals burned card name");var owner=LanProtocol.View(g,0,"burn",1).VisualEvents.Single(e=>e.Kind=="burn");var opponentView=LanProtocol.View(g,1,"burn",1);var opponent=opponentView.VisualEvents.Single(e=>e.Kind=="burn");Check(owner.CardId=="VAN_CS2_029"&&opponent.CardId=="VAN_CS2_029"&&opponent.CardName==catalog.Card("VAN_CS2_029").Name&&opponent.CardText==burn.CardText&&opponent.CardCost==burn.CardCost,"Both players receive the burned card face");Check(opponentView.Log.Any(line=>line.Contains("爆牌：")&&line.Contains(catalog.Card("VAN_CS2_029").Name)),"Opponent shared log reveals burned card name");var remote=LanProtocol.ReadView(catalog,LanProtocol.Copy(opponentView));Check(remote.Players[0].Hand.Count==0&&remote.Players[0].HandCount==10&&remote.Players[0].Deck.Count==0,"Opponent hand identity stays private while counts remain public");Check(remote.VisualEvents.Single(e=>e.Kind=="burn").CardName==catalog.Card("VAN_CS2_029").Name,"Serialized opponent view retains burned card face");int sequence=g.VisualEvents.Last().Sequence;g.Draw(0,1);var fatigue=g.VisualEvents.Single(e=>e.Sequence>sequence&&e.Kind=="fatigue");Check(fatigue.Amount==1&&!g.VisualEvents.Any(e=>e.Sequence>sequence&&e.Kind=="damage"&&e.Seat==0&&e.UnitId==0),"Fatigue has one dedicated escalating visual instead of duplicate damage float");int health=p.Health;p.SecretImmuneTurn=g.Turn;g.Draw(0,1);Check(p.Health==health&&g.VisualEvents.Last(e=>e.Kind=="fatigue").Amount==0,"Immune hero fatigue does not claim damage was dealt");}
 static void Engine(){AttackEventRegression();FreezeOpportunityRegression();BurnFatiguePrivacy();var g=Game();var u=g.Summon(0,"VAN_CS2_182");Check(!g.Attack(0,u.Id,new MatchTarget(1)).Success,"Summoning sickness");u.SummonTurn=0;Check(g.Attack(0,u.Id,new MatchTarget(1)).Success&&g.Players[1].Health==26,"Attack damage");Check(!g.Attack(0,u.Id,new MatchTarget(1)).Success,"Attack exhausted");g=Game();int h=Hand(g,"CS2_029");Check(!g.Play(0,h).Success&&g.Players[0].Mana==10&&g.Players[0].Hand.Count==1,"Invalid target atomic");Check(g.Play(0,h,new MatchTarget(1)).Success&&g.Players[1].Health==24,"Fireball");}
 static void Library(){var rules=new MatchRules(catalog);Check(catalog.Deckable(catalog.Pool("classic-2014")).Count==382,"Frozen pool");var deck=rules.TrainingDeck("MAGE");string code=DeckCode.Encode(catalog,deck);Check(DeckCode.Decode(catalog,code,deck.PoolId).Count==30,"Deckcode roundtrip");Check(!rules.Supports(new CardRecord{Id="test:unknown",EffectId="test:missing@1",Type="SPELL"}),"Unregistered effect blocked");var custom=new CardRecord{Id="test:card",BaseId="CS2_029",SetId="test-set",EffectId="test:damage@1",Type="SPELL"};Check(!rules.Supports(custom),"Missing explicit effect stays blocked");rules.RegisterExtension(custom.EffectId,"ANY_CHARACTER",c=>c.Game.Damage(c.Target,7));Check(rules.Supports(custom),"Namespaced effect registration");var g=Game();rules.Effect(custom).Apply(new EffectContext{Game=g,Seat=0,Card=custom,Target=new MatchTarget(1)});Check(g.Players[1].Health==23,"Explicit effect does not inherit Classic Fireball");}
 static void Modes(){int starts=0;var mode=new GameModeDefinition("fixture-mode",boardSlots:3,handLimit:5,manaLimit:6,startingHealth:40,firstHand:1,secondHand:2,startingMana:4,turnStarted:(game,seat)=>starts++);GameModes.Register(mode);var g=Game(mode);Check(g.Players[0].Health==40&&g.Mode==mode,"Mode health and identity");for(int n=0;n<3;n++)g.Summon(0,"VAN_CS2_231");Check(g.Summon(0,"VAN_CS2_231")==null,"Mode board cap");g.EndTurn();Check(g.Players[1].MaxMana==6&&starts==1,"Mode mana and turn hook");var view=LanProtocol.ReadView(catalog,LanProtocol.Copy(LanProtocol.View(g,1,"m",1)));Check(view.Mode.Id==mode.Id,"Mode snapshot roundtrip");}
 static void ArenaNaxx(){var pool=ArenaDraftSession.CurrentPool(catalog);Check(pool.CardSetIds.Contains("naxxramas-2014")&&catalog.Deckable(pool).Count>=412,"Arena active pool retains Classic plus Naxx");bool neutral=false,profession=false,picked=false;for(int seed=0;seed<12;seed++){var draft=new ArenaDraftSession(catalog,12000+seed,matchRules.Supports);var view=draft.View(0);draft.Pick(0,view.Session,view.Revision,0);for(int n=0;n<30;n++){view=draft.View(0);int chosen=0;for(int i=0;i<view.Choices.Length;i++){var card=catalog.Card(view.Choices[i]);if(card.SetId=="naxxramas-2014"){if(card.CardClass=="NEUTRAL")neutral=true;else profession=true;chosen=i;}}draft.Pick(0,view.Session,view.Revision,chosen);}var deck=draft.Deck(0);Check(deck.PoolId==pool.Id&&deck.Count==30,"Naxx-inclusive draft completes valid thirty-card deck");picked|=deck.Cards.Keys.Any(id=>catalog.Card(id).SetId=="naxxramas-2014");}Check(neutral&&profession&&picked,"Naxx neutral and class cards enter offers and completed drafts");var legal=new DeckDocument{PoolId=pool.Id,ClassId="HUNTER"};legal.Cards["NAX_EX1_536"]=2;legal.Cards["FP1_007"]=28;ArenaDraftSession.Validate(catalog,legal,true);Check(new MatchEngine(catalog,legal,legal,42,mode:GameModes.Arena)!=null,"Arena starts with Naxx cards and current-era bow");legal.Cards.Remove("NAX_EX1_536");legal.Cards["VAN_EX1_536"]=2;bool blocked=false;try{ArenaDraftSession.Validate(catalog,legal,true);}catch(InvalidDataException){blocked=true;}Check(blocked,"Arena rejects superseded bow identity");legal.Cards.Remove("VAN_EX1_536");legal.Cards["FP1_023"]=2;blocked=false;try{ArenaDraftSession.Validate(catalog,legal,true);}catch(InvalidDataException){blocked=true;}Check(blocked,"Naxx inclusion retains profession restrictions");}
 static void Arena(){ArenaNaxx();var draft=new ArenaDraftSession(catalog,8042,matchRules.Supports);var first=draft.View(0);var second=draft.View(1);Check(first.Phase=="class"&&first.Choices.Length==3&&first.Choices.Distinct().Count()==3&&second.Choices.Length==3&&second.Choices.Distinct().Count()==3,"Three unique class offers per player");draft.Pick(0,first.Session,first.Revision,0);first=draft.View(0);Check(first.Phase=="cards"&&first.Choices.Length==3&&first.Choices.Distinct().Count()==3&&first.Choices.All(optionId=>{var c=catalog.Card(optionId);return c.CardClass=="NEUTRAL"||c.CardClass==first.ClassId;}),"Three-card offers match chosen class pool");bool stale=false;try{draft.Pick(0,first.Session,first.Revision-1,0);}catch(InvalidOperationException){stale=true;}Check(stale,"Stale draft revision rejected");for(int seat=0;seat<2;seat++){if(seat==1){var state=draft.View(seat);draft.Pick(seat,state.Session,state.Revision,0);}for(int n=0;n<ArenaDraftSession.DraftSize;n++){var state=draft.View(seat);draft.Pick(seat,state.Session,state.Revision,n%state.Choices.Length);}}var deck=draft.Deck(0);Check(deck.Count==30&&draft.Deck(1).Count==30,"Both drafts produce 30-card decks");string arenaCardId=catalog.Deckable(catalog.Pool("classic-2014")).First(c=>(c.CardClass=="NEUTRAL"||c.CardClass==deck.ClassId)&&matchRules.Supports(c)).Id;deck.Cards.Clear();deck.Cards[arenaCardId]=30;ArenaDraftSession.Validate(catalog,deck,true);Check(deck.Count==30,"Arena ignores constructed-deck copy limits");deck.Cards[arenaCardId]=29;bool incomplete=false;try{ArenaDraftSession.Validate(catalog,deck,true);}catch(InvalidDataException){incomplete=true;}Check(incomplete,"Arena requires exactly 30 cards");}
 static void Enchantments(){var g=Game();var u=g.Summon(0,"VAN_CS2_182");g.Buff(new MatchTarget(0,u.Id),3,2);u.CommandingShoutTurn=g.Turn;var copy=new BattleUnit();BattleUnitCopies.Copy(u,copy);copy.BuffAttack++;Check(u.BuffAttack==3&&copy.BuffAttack==4,"Copy enchantments independent");g.Silence(new MatchTarget(0,u.Id));Check(u.BuffAttack==0&&u.BuffHealth==0&&u.CommandingShoutTurn==-1,"Silence clears enchantments");Check(copy.BuffAttack==4,"Silence leaves copied effects intact");}
 static void Privacy(){Check(LanProtocol.CompatibilityError("cards:app","cards:app")==null,"Same exact build and catalog accepted");Check(LanProtocol.CompatibilityError("cards:app","other:app").Contains("牌库数据版本不同"),"Catalog mismatch distinguished from saved deck");Check(LanProtocol.CompatibilityError("cards:app","cards:other").Contains("程序构建版本不同"),"Same-version different builds identified");Check(LanProtocol.CompatibilityError("cards:app",null)!=null,"Missing compatibility identifier still blocked");var g=Game();Hand(g,"EX1_287");g.Play(0,g.Players[0].Hand[0].Id);var v=LanProtocol.View(g,1,"p",1);string wire=JsonData.Serializer().Serialize(v);Check(v.Players[0].Hand.Length==0&&v.Players[0].Public.SecretCount==1,"Masked hand and count");Check(!wire.Contains("VAN_EX1_287")&&!wire.Contains("法术反制"),"No secret identity");Check(!typeof(PublicPlayerState).GetFields().Any(f=>f.Name=="Deck"||f.Name=="Hand"||f.Name=="Secrets"),"Public whitelist");var previous=LanProtocol.ReadView(catalog,v);int acknowledged=previous.Log.Count;g.Log.Add("next public action");var delta=LanProtocol.View(g,1,"p",2,acknowledged);Check(delta.Log.Length==1&&delta.LogStart==acknowledged,"Only new log entries sent");var next=LanProtocol.ReadView(catalog,delta,previous);Check(next.Log.SequenceEqual(g.Log),"Delta reconstructs full history");Check(LanProtocol.ReadView(catalog,delta,next).Log.SequenceEqual(g.Log),"Repeated delta does not duplicate logs");}
 static void Resolution(){LethalStatMutationRegression();var queue=new ResolutionQueue();var order=new List<int>();queue.Enqueue(()=>{order.Add(1);queue.Enqueue(()=>order.Add(3));queue.Drain();});queue.Enqueue(()=>order.Add(2));queue.Drain();Check(order.SequenceEqual(new[]{1,2,3})&&queue.Count==0,"Reentrant FIFO");var g=Game();var smith=g.Summon(0,"VAN_EX1_402");smith.DamageTaken=3;g.Summon(0,"VAN_CS2_231");g.DamageBatch(()=>{foreach(var t in g.Characters(0,false))g.Damage(t,1);});g.Cleanup();Check(g.Players[0].Armor==2,"Dying listeners persist for damage batch");}
 static void Warrior(){var g=Game();g.Players[0].ClassId="WARRIOR";var u=g.Summon(0,"VAN_CS2_182");g.Play(0,Hand(g,"NEW1_036"));g.Damage(new MatchTarget(0,u.Id),20);Check(u.Health==1,"Shout caps damage");g.EndTurn();g.Damage(new MatchTarget(0,u.Id),1);g.Cleanup();Check(g.Players[0].Board.Count==0,"Shout expiry");g=Game();g.Players[0].ClassId="WARRIOR";g.Equip(0,"VAN_EX1_411");u=g.Summon(1,"VAN_CS2_182");g.Attack(0,0,new MatchTarget(1,u.Id));Check(g.Players[0].WeaponAttack==6&&g.Players[0].WeaponDurability==1,"Gorehowl minion wear");}
 static void Secrets(){var g=Game();g.Play(0,Hand(g,"EX1_287"));g.EndTurn();g.Play(1,Hand(g,"CS2_029",1),new MatchTarget(0));Check(g.Players[0].Health==30&&g.Players[0].SecretCount==0,"Counterspell");Check(g.Log.Any(x=>x.Contains("奥秘触发：法术反制")),"Reveal");g=Game();g.Play(0,Hand(g,"EX1_295"));g.EndTurn();g.Players[0].Health=2;Check(g.Damage(new MatchTarget(0),6)==0&&g.Players[0].Health==2,"Ice Block");g.EndTurn();Check(g.Damage(new MatchTarget(0),1)==1,"Immunity expires");}
 static void Rogue(){var g=Game();var u=g.Summon(0,"VAN_CS2_182");g.Play(0,Hand(g,"EX1_144"),new MatchTarget(0,u.Id));Check(g.HandCost(0,g.Players[0].Hand.Single())==2,"Shadowstep instance discount");g.Play(0,Hand(g,"EX1_145"));Check(g.Players[0].PreparationDiscount==3,"Preparation");g.EndTurn();Check(g.Players[0].PreparationDiscount==0,"Preparation expiry");}
 static void Deaths(){var g=Game();var u=g.Summon(0,"VAN_EX1_556");u.DamageTaken=u.MaxHealth;g.Cleanup();Check(g.Players[0].Board.Single().CardId=="VAN_skele21","Deathrattle");Check(g.Graveyard.Count==1,"Death recorded");}
 static void Combo(){var g=Game();g.Play(0,Hand(g,"EX1_145"));var u=g.Summon(1,"VAN_CS2_182");g.Play(0,Hand(g,"EX1_124"),new MatchTarget(1,u.Id));Check(u.Health==1,"Eviscerate combo");g.EndTurn();Check(g.CardsPlayed==0,"Combo counter resets");}
 static void Overload(){var g=Game();g.Play(0,Hand(g,"EX1_238"),new MatchTarget(1));Check(g.Players[0].Overload==1,"Overload queued");g.EndTurn();g.EndTurn();Check(g.Players[0].LockedMana==1,"Overload locks next turn");}
 static void Opening(){var decks=new[]{matchRules.TrainingDeck("MAGE"),matchRules.TrainingDeck("ROGUE")};var seen=new HashSet<int>();for(int seed=0;seed<20;seed++){var host=new LanHostGame(catalog,decks[0],decks[1],seed);var g=host.Game;seen.Add(g.FirstSeat);Check(g.Players[g.FirstSeat].Hand.Count==3&&g.Players[g.SecondSeat].Hand.Count==4,"Random opening hand allocation");g.Mulligan(g.SecondSeat,new int[0]);Check(!g.MulliganComplete&&!g.Players.Any(p=>p.Hand.Any(h=>h.CardId=="GAME_COIN")),"No premature coin");g.Mulligan(g.FirstSeat,new int[0]);Check(g.Active==g.FirstSeat&&g.Players[g.FirstSeat].Hand.Count==4&&g.Players[g.FirstSeat].Mana==1&&g.Players[g.SecondSeat].Hand.Count==5&&g.Players[g.SecondSeat].Hand.Count(h=>h.CardId=="GAME_COIN")==1,"First draw and second coin follow randomized roles");var view=LanProtocol.ReadView(catalog,LanProtocol.View(g,1,"opening",1));Check(view.FirstSeat==g.FirstSeat&&view.Players[0].ClassId=="MAGE"&&view.Players[1].ClassId=="ROGUE"&&view.Players[0].Hand.Count==0,"Role synchronized without swapping seats or leaking hand");g.EndTurn();Check(g.Active==g.SecondSeat&&g.Players[g.SecondSeat].Mana==1,"Second player gets own first turn");}Check(seen.SetEquals(new[]{0,1}),"Host and guest both win opening coin flip");}
 static void Shadowstep(){var g=MatchFixture("ROGUE");var u=g.Summon(0,"VAN_CS2_182");g.Play(0,Hand(g,"EX1_144"),new MatchTarget(0,u.Id));var first=g.Players[0].Hand.Single();Check(first.CostAdjustment==-2&&g.HandCost(0,first)==2,"First shadowstep minus two");g.Play(0,first.Id);u=g.Players[0].Board.Single();g.Silence(new MatchTarget(0,u.Id));g.Play(0,Hand(g,"EX1_144"),new MatchTarget(0,u.Id));var second=g.Players[0].Hand.Single();Check(second.CostAdjustment==-2&&g.HandCost(0,second)==2,"Second shadowstep applies fresh minus two after replay");g.Play(0,second.Id);u=g.Players[0].Board.Single();g.Play(0,Hand(g,"EX1_144"),new MatchTarget(0,u.Id));Check(g.Players[0].Hand.Single().CostAdjustment==-2&&g.HandCost(0,g.Players[0].Hand.Single())==2,"Repeated shadowstep never stacks across replay");int other=Hand(g,"CS2_182");Check(g.HandCost(0,g.Players[0].Hand.Single(h=>h.Id==other))==4,"Different copy remains full price");}
